/* C API of the Rust port of `src/checksum.c`, generated by everything-rust. */
#ifndef CHECKSUM_RS_H
#define CHECKSUM_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

uint32_t adler32(const char *data);
uint32_t fnv1a(const char *data);
int clamp(int value, int low, int high);
long gcd(long a, long b);
double mean3(double a, double b, double c);

/* The same functions under `everything_rust_` names, for shadow runs. */
uint32_t everything_rust_adler32(const char *data);
uint32_t everything_rust_fnv1a(const char *data);
int everything_rust_clamp(int value, int low, int high);
long everything_rust_gcd(long a, long b);
double everything_rust_mean3(double a, double b, double c);

#endif /* CHECKSUM_RS_H */
